<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {Plus,Upload,Download,Heart,Square,Image,Music,Film,ArrowRight} from 'lucide-vue-next'
import Sheet from '../components/Sheet.vue'
import {useLocal} from '../stores/local'
import {ContractError,type Document,type DomainKind} from '../domain/local-contract'
import {importAsset,downloadAsset,linkAsset} from './assets'
import {prepareMedia,executeMedia,saveMediaResult,stopMedia,recoverMedia,mediaPending} from './runtime'
import {assetLinkKinds,type LocalAsset,type AssetLink,type MediaJob} from './contract'
import AssetView from './AssetView.vue'
import OriginalPackPanel from './OriginalPackPanel.vue'
import type {MediaCompose} from './compose'
import {LocalRecording} from './recorder'
import {videoDraft} from './video-runtime'
const store=useLocal(),route=useRoute(),assets=ref<Document<LocalAsset>[]>([]),jobs=ref<Document<MediaJob>[]>([]),error=ref(''),busy=ref(false),page=ref(0),search=ref(''),filter=ref('all'),favorites=ref(false),retired=ref(false),detail=ref<Document<LocalAsset>|null>(null),workbench=ref(!!route.query.source||!!route.query.draft),type=ref<MediaJob['type']>('image'),prompt=ref(''),referenceId=ref(''),source=ref<AssetLink|null>(null),role=ref<AssetLink['role']>('illustration-after'),targets=ref<Document<{name?:string;title?:string}>[]>([]),targetId=ref(''),storage=ref({used:0,limit:512*1024*1024}),selectedJob=ref(''),transcript=ref(''),transcriptRevision=ref(0),received=ref(0)
const filtered=computed(()=>assets.value.filter(row=>row.value.retired===retired.value&&(filter.value==='all'||row.value.mediaKind===filter.value)&&(!favorites.value||row.value.favorite)&&row.value.name.toLocaleLowerCase().includes(search.value.toLocaleLowerCase()))),shown=computed(()=>filtered.value.slice(page.value*80,page.value*80+80)),references=computed(()=>assets.value.filter(row=>!row.value.retired&&row.value.mediaKind===(type.value==='asr'?'audio':'image'))),job=computed(()=>jobs.value.find(row=>row.id===selectedJob.value)||null),labels={queued:'待开始',calling:'正在生成',completed:'已保存',failed:'未完成',unknown:'请求待核对',cancelled:'已停止',persistence_failed:'等待保存'}
const recording=ref(false),recordedSeconds=ref(0);let recorder:LocalRecording|null=null
const originalOpen=ref(false)
const lifecycle=new AbortController()
const router=useRouter()
let disposed=false,epoch=0,poll:ReturnType<typeof setInterval>|null=null
async function load(){const vault=store.vault,ticket=++epoch;if(!vault)return;const [all,records,size]=await Promise.all([vault.list<LocalAsset>('asset'),vault.list<MediaJob>('mediaJob'),vault.read<{used:number;limit:number}>('settings:media-storage')]);if(disposed||store.vault!==vault||ticket!==epoch)return;assets.value=all.sort((a,b)=>b.value.createdAt.localeCompare(a.value.createdAt));jobs.value=records.sort((a,b)=>b.value.createdAt.localeCompare(a.value.createdAt));storage.value=size?.value||storage.value;if(detail.value)detail.value=all.find(row=>row.id===detail.value?.id)||null;for(const row of records)if(row.value.status==='calling')try{const recovered=await recoverMedia(vault,row);if(disposed||ticket!==epoch)return;const index=jobs.value.findIndex(item=>item.id===row.id);if(index>=0)jobs.value[index]=recovered}catch(e){if(!disposed)error.value=(e as Error).message}}
async function microphone(){if(recording.value){const vault=store.vault;if(!vault||!recorder)return;try{const file=await recorder.finish();recording.value=false;const asset=await importAsset(vault,file,[],lifecycle.signal);if(disposed||store.vault!==vault)return;await load();referenceId.value=asset.id;type.value='asr'}catch(e){error.value=(e as Error).message;recorder?.cancel();recording.value=false}return}recordedSeconds.value=0;recorder=new LocalRecording(seconds=>recordedSeconds.value=seconds);recording.value=true;try{await recorder.start()}catch(e){if(!disposed){error.value=(e as Error).message;recording.value=false}}}
function cancelRecording(){recorder?.cancel();recording.value=false}
async function animate(){const vault=store.vault,row=detail.value;if(!vault||!row)return;try{const destination=await videoDraft(vault,'',row.value.links[0]||null,row.id,lifecycle.signal);if(!disposed&&store.vault===vault&&vault.unlocked)await router.push(destination)}catch(e){if(!disposed)error.value=(e as Error).message}}
async function imported(event:Event){const files=(event.target as HTMLInputElement).files,vault=store.vault;if(!vault||!files||busy.value)return;busy.value=true;error.value='';try{if(files.length>20)throw new ContractError('ASSET_BATCH','单批最多导入 20 个素材');for(const file of files){if(disposed||store.vault!==vault||!vault.unlocked)break;await importAsset(vault,file,source.value?[source.value]:[],lifecycle.signal)}await load()}catch(e){if(!disposed)error.value=(e as Error).message}finally{if(!disposed)busy.value=false;(event.target as HTMLInputElement).value=''}}
async function changeAsset(row:Document<LocalAsset>,changes:Partial<Pick<LocalAsset,'favorite'|'retired'|'name'|'links'>>){const vault=store.vault;if(!vault)return;try{await vault.commit(crypto.randomUUID(),'asset',row.id,row.revision,{...row.value,...changes});await load()}catch(e){if(!disposed)error.value=(e as Error).message}}
async function attach(){const vault=store.vault,row=detail.value,target=targets.value.find(item=>item.id===targetId.value);if(!vault||!row||!target)return;try{await linkAsset(vault,row,[{targetId:target.id,targetKind:target.kind,targetRevision:target.revision,role:role.value}]);await load()}catch(e){error.value=(e as Error).message}}
function targetPath(link:AssetLink){return link.targetKind==='story'||link.targetKind==='branch'?'/local/read/'+(link.targetKind==='story'?link.targetId:(targets.value.find(row=>row.id===link.targetId)?.value as {storyId?:string})?.storyId||'')+(link.targetKind==='branch'?'?branch='+encodeURIComponent(link.targetId):link.branchId?'?branch='+encodeURIComponent(link.branchId):''):link.targetKind==='card'?'/local/characters':link.targetKind==='companion'?'/local/companions/'+link.targetId:link.targetKind==='session'?'/local/chat/'+link.targetId:'/local/gallery'}
async function generate(variant=false){const vault=store.vault;if(!vault||busy.value)return;busy.value=true;error.value='';received.value=0;try{const row=await prepareMedia(vault,type.value,prompt.value,{source:source.value,referenceId:referenceId.value||undefined,variant,signal:lifecycle.signal});if(disposed||store.vault!==vault||!vault.unlocked)return;selectedJob.value=row.id;await load();workbench.value=false;if(row.value.status==='queued')await executeMedia(vault,row.id,{chunk:(_bytes,total)=>{if(!disposed)received.value=total}});await load();if(!disposed&&type.value==='asr')await selectJob(row.id)}catch(e){if(!disposed){error.value=(e as Error).message;await load().catch(()=>{})}}finally{if(!disposed)busy.value=false}}
async function retry(){const vault=store.vault,row=job.value;if(!vault||!row||busy.value)return;busy.value=true;try{await saveMediaResult(vault,row.id);await load();error.value=''}catch(e){if(!disposed)error.value=(e as Error).message}finally{if(!disposed)busy.value=false}}
async function selectJob(id:string){selectedJob.value=id;const vault=store.vault,row=jobs.value.find(row=>row.id===id);if(!vault||!row)return;const draft=await vault.read<{jobId:string;text:string}>('settings:media-transcript:'+id);if(disposed||selectedJob.value!==id)return;transcript.value=draft?.value.text??row.value.text??'';transcriptRevision.value=draft?.revision||0}
async function copyTranscript(){try{await navigator.clipboard.writeText(transcript.value)}catch{error.value='无法访问剪贴板，请选择文字复制'}}
async function saveTranscript(){const vault=store.vault,row=job.value;if(!vault||!row)return;try{await vault.commit(crypto.randomUUID(),'settings','settings:media-transcript:'+row.id,transcriptRevision.value,{jobId:row.id,text:transcript.value});transcriptRevision.value++;error.value=''}catch(e){error.value=(e as Error).message}}
async function limits(){const vault=store.vault;if(!vault)return;try{const row=await vault.read('settings:media-storage');await vault.commit(crypto.randomUUID(),'settings','settings:media-storage',row?.revision||0,{...storage.value});await load()}catch(e){error.value=(e as Error).message}}
function changed(event:Event){if((event as CustomEvent<{vaultId:string}>).detail?.vaultId===store.vault?.id)void load().catch(()=>{})}
onMounted(async()=>{window.addEventListener('reader-local-locked',cancelRecording);window.addEventListener('reader-media-changed',changed);poll=setInterval(()=>void load().catch(()=>{}),3000);try{await load();const vault=store.vault;if(!vault)return;const results=await Promise.all(assetLinkKinds.filter(kind=>kind!=='paragraph'&&kind!=='message').map(kind=>vault.list<{name?:string;title?:string}>(kind)));if(disposed)return;targets.value=results.flat();if(typeof route.query.draft==='string'){const draft=await vault.read<MediaCompose>(route.query.draft);if(draft?.value.assetType==='media-compose'){type.value=draft.value.type;prompt.value=draft.value.prompt;source.value=draft.value.source;referenceId.value=draft.value.referenceId||'';targetId.value=draft.value.source?.targetId||''}else throw new Error('素材草稿不存在')}if(typeof route.query.source==='string'){const target=await vault.read(route.query.source);if(!target||!assetLinkKinds.includes(target.kind))throw new Error('找不到素材来源');const revision=route.query.revision?Number(route.query.revision):target.revision;if(revision!==target.revision)throw new Error('来源已变化，请返回重新选择');const allowed=['cover','illustration-before','illustration-after','background','portrait','attachment','speech'];source.value={targetId:target.id,targetKind:target.kind,targetRevision:revision,role:allowed.includes(String(route.query.role))?String(route.query.role) as AssetLink['role']:'illustration-after',...(typeof route.query.paragraph==='string'?{paragraphId:route.query.paragraph}:{}),...(typeof route.query.branch==='string'?{branchId:route.query.branch}:{})};targetId.value=target.id}if(route.query.type==='tts'||route.query.type==='asr'||route.query.type==='edit')type.value=route.query.type;if(typeof route.query.reference==='string')referenceId.value=route.query.reference;if(route.query.job)await selectJob(String(route.query.job));if(typeof route.query.asset==='string')detail.value=assets.value.find(row=>row.id===route.query.asset)||null}catch(e){if(!disposed)error.value=(e as Error).message}})
onUnmounted(()=>{disposed=true;lifecycle.abort();recorder?.cancel();window.removeEventListener('reader-local-locked',cancelRecording);epoch++;if(poll)clearInterval(poll);window.removeEventListener('reader-media-changed',changed);assets.value=[];jobs.value=[];detail.value=null;prompt.value='';transcript.value=''})
</script>
<template><section><div class="final-page-heading"><div class="final-heading-copy"><h1>画廊</h1><span class="final-subtle">{{assets.length}} 个素材</span></div><div class="final-grid-actions"><label class="final-gallery-upload"><Upload :size="18"/>导入<input type="file" multiple accept="image/png,image/jpeg,image/webp,image/gif,audio/*,video/mp4,video/webm" :disabled="busy" @change="imported"></label><button @click="originalOpen=true">原创素材</button><RouterLink to="/local/video" class="final-text-link">视频创作</RouterLink><button class="final-primary" @click="workbench=true"><Plus :size="18"/>创作</button></div></div><p v-if="error" class="final-error" role="alert">{{error}}</p><div class="final-gallery-filters"><input v-model="search" type="search" aria-label="搜索素材" placeholder="搜索素材" @input="page=0"><select v-model="filter" aria-label="素材类型" @change="page=0"><option value="all">全部</option><option value="image">图片</option><option value="audio">声音</option><option value="video">视频</option></select><button :aria-pressed="favorites" @click="favorites=!favorites;page=0"><Heart :size="16"/>收藏</button><button :aria-pressed="retired" @click="retired=!retired;page=0">已收起</button></div><div class="final-gallery-grid"><article v-for="row in shown" :key="row.id"><button class="final-gallery-open" @click="detail=row"><AssetView :asset="row"/><span>{{row.value.name}}</span></button><div class="final-gallery-item-meta"><Image v-if="row.value.mediaKind==='image'" :size="14"/><Music v-else-if="row.value.mediaKind==='audio'" :size="14"/><Film v-else :size="14"/><span>{{(row.value.bytes/1024).toFixed(0)}} KB</span><button :aria-label="row.value.favorite?'取消收藏':'收藏素材'" :aria-pressed="row.value.favorite" @click="changeAsset(row,{favorite:!row.value.favorite})"><Heart :size="16"/></button></div></article></div><div v-if="!shown.length" class="final-empty"><Image :size="36"/><h2>{{search?'没有匹配的素材':'收下故事里的画面与声音'}}</h2></div><div v-if="filtered.length>80" class="final-gallery-pages"><button :disabled="page===0" @click="page--">上一页</button><span>{{page+1}} / {{Math.ceil(filtered.length/80)}}</span><button :disabled="(page+1)*80>=filtered.length" @click="page++">下一页</button></div><section v-if="jobs.length" class="final-gallery-jobs"><h2>创作记录</h2><select :value="selectedJob" aria-label="媒体创作记录" @change="selectJob(($event.target as HTMLSelectElement).value)"><option value="">选择记录</option><option v-for="row in jobs.slice(0,200)" :key="row.id" :value="row.id">{{new Date(row.value.createdAt).toLocaleString()}} · {{row.value.type}} · {{labels[row.value.status]}}</option></select><template v-if="job"><p role="status">{{labels[job.value.status]}}{{received?' · 已收到 '+(received/1024).toFixed(0)+' KB':''}}</p><p v-if="job.value.error" class="final-subtle">{{job.value.error}}</p><div class="final-grid-actions"><button v-if="['queued','calling'].includes(job.value.status)" @click="store.vault&&stopMedia(store.vault,job.id)"><Square :size="16"/>停止</button><button v-if="store.vault&&mediaPending(store.vault,job.id)" :disabled="busy" @click="retry">只重试保存</button><button v-if="job.value.outputAssetId" @click="detail=assets.find(row=>row.id===job?.value.outputAssetId)||null">查看结果<ArrowRight :size="16"/></button></div><div v-if="job.value.type==='asr'&&job.value.text!==null" class="final-gallery-transcript"><label>转录文本<textarea v-model="transcript" rows="8" maxlength="1000000"/></label><div class="final-grid-actions"><button @click="saveTranscript">保存校订</button><button @click="copyTranscript">复制文字</button></div></div><details><summary>请求详情</summary><p>{{job.value.configSnapshot.modelId}} · {{job.value.requestId||'供应商未提供请求 ID'}}</p><p>输入 {{job.value.inputTokens??'未提供'}} · 输出 {{job.value.outputTokens??'未提供'}} · 价格未提供</p><p>{{job.value.prompt}}</p></details></template></section><details class="final-gallery-storage"><summary>存储 · {{(storage.used/1024/1024).toFixed(1)}} MiB</summary><label>存储上限<select v-model.number="storage.limit"><option :value="128*1024*1024">128 MiB</option><option :value="512*1024*1024">512 MiB</option><option :value="1024*1024*1024">1 GiB</option></select></label><button @click="limits">保存上限</button></details></section>
<OriginalPackPanel v-if="originalOpen" @close="originalOpen=false" @saved="load()"/>
<Sheet v-if="workbench" title="创作素材" @close="!busy&&(workbench=false)"><form class="final-card-form" @submit.prevent="generate()"><label>用途<select v-model="type" aria-label="用途"><option value="image">生成图片</option><option value="edit">参考图编辑</option><option value="tts">在线配音</option><option value="asr">录音转文字</option></select></label><div v-if="type==='asr'" class="final-grid-actions"><button type="button" @click="microphone">{{recording?'结束录音 · '+recordedSeconds.toFixed(1)+' 秒':'录音'}}</button><button v-if="recording" type="button" @click="cancelRecording">取消</button></div><label v-if="type==='edit'||type==='asr'">{{type==='edit'?'参考图片':'录音'}}<select v-model="referenceId" :aria-label="type==='asr'?'录音':'参考图片'" required><option value="">选择素材</option><option v-for="row in references" :key="row.id" :value="row.id">{{row.value.name}}</option></select></label><label v-if="type!=='asr'">{{type==='tts'?'配音文字':'画面描述'}}<textarea v-model="prompt" rows="6" :maxlength="type==='tts'?4096:20000" required/></label><p v-if="source" class="final-subtle">关联 · {{targets.find(row=>row.id===source?.targetId)?.value.title||targets.find(row=>row.id===source?.targetId)?.value.name||'所选段落'}}</p><RouterLink to="/local/settings/media" class="final-text-link">媒体通道</RouterLink><p v-if="error" class="final-error" role="alert">{{error}}</p><button class="final-primary" :disabled="busy">{{busy?'正在生成…':type==='asr'?'转录':'开始创作'}}</button></form></Sheet>
<Sheet v-if="detail" :title="detail.value.name" @close="detail=null"><AssetView :asset="detail" full/><div class="final-grid-actions final-gallery-detail-actions"><button @click="store.vault&&downloadAsset(store.vault,detail)"><Download :size="18"/>下载</button><button @click="changeAsset(detail,{favorite:!detail.value.favorite})"><Heart :size="18"/>{{detail.value.favorite?'取消收藏':'收藏'}}</button><button @click="changeAsset(detail,{retired:!detail.value.retired})">{{detail.value.retired?'重新显示':'收起'}}</button><button v-if="detail.value.mediaKind==='image'" @click="animate">让画面动起来</button><button v-if="detail.value.mediaKind==='image'" @click="referenceId=detail.id;type='edit';detail=null;workbench=true">以此图创作</button></div><p class="final-subtle">{{detail.value.width&&detail.value.height?detail.value.width+' × '+detail.value.height+' · ':''}}{{detail.value.duration?detail.value.duration.toFixed(1)+' 秒 · ':''}}{{detail.value.origin==='import'?'导入':'生成'}} · {{(detail.value.bytes/1024).toFixed(0)}} KB</p><h3>关联位置</h3><article v-for="(link,index) in detail.value.links" :key="index" class="final-gallery-link"><RouterLink :to="targetPath(link)">{{targets.find(row=>row.id===link.targetId)?.value.title||targets.find(row=>row.id===link.targetId)?.value.name||'来源'}} · v{{link.targetRevision}}<ArrowRight :size="16"/></RouterLink><button aria-label="移除此关联" @click="changeAsset(detail,{links:detail.value.links.filter((_,i)=>i!==index)})">移除</button></article><form class="final-card-form" @submit.prevent="attach"><label>关联到<select v-model="targetId" required><option value="">选择故事或角色</option><option v-for="target in targets" :key="target.id" :value="target.id">{{target.value.title||target.value.name||target.id}}</option></select></label><label>位置<select v-model="role"><option value="cover">封面</option><option value="background">背景</option><option value="portrait">立绘</option><option value="attachment">附件</option></select></label><button>添加关联</button></form></Sheet>
</template>
<style scoped>.final-gallery-filters{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:24px}.final-gallery-filters input{flex:1;min-width:130px;width:auto}.final-gallery-filters select{width:150px}.final-gallery-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:20px}.final-gallery-grid article{min-width:0}.final-gallery-open{display:grid;gap:10px;padding:0;border:0;background:transparent;width:100%;text-align:left;align-content:start;min-height:44px}.final-gallery-open>span{padding:0 4px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;width:100%;font-size:14px}.final-gallery-item-meta{display:flex;align-items:center;gap:6px;color:var(--muted);font-size:12px;margin:4px}.final-gallery-item-meta button{margin-left:auto;border:0;background:transparent;min-height:44px;min-width:44px}.final-gallery-upload{cursor:pointer;display:flex;align-items:center;gap:8px;min-height:44px}.final-gallery-upload input{display:none}.final-gallery-pages,.final-gallery-link{display:flex;justify-content:space-between;align-items:center;gap:12px;margin:24px 0}.final-gallery-jobs{margin:40px 0;padding-top:24px;border-top:1px solid var(--edge);display:grid;gap:16px}.final-gallery-jobs select{max-width:100%}.final-gallery-transcript{display:grid;gap:14px}.final-gallery-storage{margin-top:36px;color:var(--muted)}.final-gallery-detail-actions{margin:20px 0}.final-gallery-link a{display:flex;align-items:center;gap:8px;overflow-wrap:anywhere;color:var(--accent)}@media(max-width:540px){.final-gallery-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.final-gallery-filters select{max-width:105px}.final-gallery-upload{font-size:14px}}</style>
